//@ aux-crate=macro-spans-aux.rs
//! Items and statements generated by macros, checked by the `macro_spans` test in
//! `crate_data.rs`.
macro_rules! make_fn {
    ($name:ident) => {
        pub fn $name() -> u32 {
            1
        }
    };
}
make_fn!(local);

macro_rules! outer {
    ($name:ident) => {
        make_fn!($name);
    };
}
outer!(nested);

macro_spans_aux::make_fn_aux!(from_aux);

include!("macro-spans-included.rs");
make_fn_included!(from_included);

#[path = "macro-spans-pathmod.rs"]
pub mod pathmod;
pathmod::make_fn_pathmod!(from_pathmod);

#[derive(Clone)]
pub struct Derived(u32);

macro_rules! double {
    ($e:expr) => {
        $e + $e
    };
}
pub fn macro_expr(x: u32) -> u32 {
    double!(x)
}

pub fn desugarings(x: Option<u32>) -> Option<u32> {
    let mut sum = 0;
    for i in 0..x? {
        sum += i;
    }
    Some(sum)
}
